// Planner v3.2: minimal personal-looking html. One font stack, no images,
// no colors beyond text. Paragraph breaks only.
function plainHtml(text) {
  const esc = text.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
  const paras = esc.split('\n\n').map((pp) => `<p style="margin:0 0 14px;">${pp.replace(/\n/g, '<br>')}</p>`).join('');
  return `<div style="font-family:-apple-system,Segoe UI,Arial,sans-serif;font-size:15px;line-height:1.6;color:#1A1D20;">${paras}</div>`;
}

// Hosted split bill: KV record sb:{token} =
// { title, totalFmt, shareFmt, headcount, payerName, userName,
//   people: [{id,name,paid}], my: {included, label, paid} }
const SPLIT_TTL = 15 * 24 * 3600; // 15 days, then the link retires itself

async function handleSplitRoutes(request, env, url) {
  const seg = url.pathname.split('/').filter(Boolean); // e.g. ['split','abc']
  const esc = (v) => String(v ?? '').replace(/[<>&"]/g, '');

  // POST /split-create : store the bill, email the payer their manage link.
  if (url.pathname === '/split-create' && request.method === 'POST') {
    let body;
    try { body = await request.json(); } catch { return json({ ok: false, reason: 'Bad request' }, 400); }
    const clean = (v, n) => String(v ?? '').replace(/[<>]/g, '').trim().slice(0, n);
    const record = {
      title: clean(body.title, 80) || 'a shared bill',
      totalFmt: clean(body.totalFmt, 30),
      shareFmt: clean(body.shareFmt, 30),
      headcount: Math.min(Math.max(parseInt(body.headcount, 10) || 2, 2), 50),
      payerName: clean(body.payerName, 60) || 'the payer',
      userName: clean(body.userName, 60) || 'A SaveCents user',
      people: (Array.isArray(body.people) ? body.people : []).slice(0, 20).map((pp) => ({
        id: clean(pp.id, 40), name: clean(pp.name, 60) || 'Someone', paid: false,
        // Planner v5: per-person share on custom bills. Absent (older app
        // versions) falls back to the bill-level shareFmt at render time.
        shareFmt: clean(pp.shareFmt, 30) || undefined,
      })),
      my: {
        included: !!body.includeUser, label: clean(body.userLabel, 60) || 'the SaveCents user', paid: false,
        shareFmt: clean(body.userShareFmt, 30) || undefined,
      },
      // false = custom amounts; anything else (including absent) = even.
      even: body.even !== false,
    };
    if (!record.totalFmt || !record.shareFmt) return json({ ok: false, reason: 'Bad request' }, 400);
    const token = token24();
    await env.OTP_KV.put(`sb:${token}`, JSON.stringify(record), { expirationTtl: SPLIT_TTL });
    const link = `${url.protocol}//${url.host}/split/${token}`;

    const payerEmail = String(body.payerEmail ?? '').trim().toLowerCase();
    let emailed = false;
    if (validEmail(payerEmail)) {
      const mathBit = record.even === false
        ? `${record.totalFmt}, split by what each person got`
        : `${record.totalFmt}, split ${record.headcount} ways, ${record.shareFmt} each`;
      const text = `Hi ${record.payerName},\n\nYou covered ${record.title} (${mathBit}).\n\nThis link was generated by ${record.userName}. You can manage the bill splitting here and tick off who already paid you:\n\n${link}\n\nThe link expires in 15 days.\n\n${record.userName}, via ${env.SENDER_NAME}`;
      const res = await fetch('https://api.brevo.com/v3/smtp/email', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', 'api-key': env.BREVO_API_KEY },
        body: JSON.stringify({
          sender: { name: `${record.userName} via ${env.SENDER_NAME}`, email: env.SENDER_EMAIL },
          to: [{ email: payerEmail }],
          subject: `You covered ${record.title}, here's your tracker`,
          textContent: text,
          htmlContent: splitManageHtml(env.SENDER_NAME, record, link, `${url.protocol}//${url.host}/logo-v2.png`),
        }),
      });
            emailed = res.ok;
      if (!res.ok) console.log('split manage email failed', res.status);
    }
    return json({ ok: true, token, url: link, emailed });
  }

  // GET /split-state/:token : the app pulls the payer's ticks.
  if (seg[0] === 'split-state' && seg[1] && request.method === 'GET') {
    const raw = await env.OTP_KV.get(`sb:${seg[1]}`);
    if (!raw) return json({ ok: false, reason: 'gone' }, 404);
    const r = JSON.parse(raw);
    return json({ ok: true, people: r.people.map((pp) => ({ id: pp.id, paid: pp.paid })), myPaid: !!r.my?.paid });
  }

  // POST /split-set/:token : the app pushes a tick (its own share or a
  // person it marked), keeping both sides matched.
  if (seg[0] === 'split-set' && seg[1] && request.method === 'POST') {
    let body;
    try { body = await request.json(); } catch { return json({ ok: false, reason: 'Bad request' }, 400); }
    const raw = await env.OTP_KV.get(`sb:${seg[1]}`);
    if (!raw) return json({ ok: false, reason: 'gone' }, 404);
    const r = JSON.parse(raw);
    if (body.mine !== undefined) r.my.paid = !!body.mine;
    if (body.pid) r.people = r.people.map((pp) => (pp.id === body.pid ? { ...pp, paid: !!body.paid } : pp));
    await env.OTP_KV.put(`sb:${seg[1]}`, JSON.stringify(r), { expirationTtl: SPLIT_TTL });
    return json({ ok: true });
  }

  // The manage page itself. GET renders, form POST toggles then bounces back.
  if (seg[0] === 'split' && seg[1]) {
    const key = `sb:${seg[1]}`;
    const raw = await env.OTP_KV.get(key);
    if (!raw) {
      return new Response('<meta name="viewport" content="width=device-width,initial-scale=1"><body style="font-family:-apple-system,Segoe UI,Arial,sans-serif;padding:40px 24px;color:#1A1D20;"><h3>This link has expired</h3><p>Split links last 15 days. Ask for a fresh one.</p></body>', { status: 404, headers: { 'Content-Type': 'text/html; charset=utf-8' } });
    }
    const r = JSON.parse(raw);

    if (request.method === 'POST') {
      const form = await request.formData();
      const pid = form.get('pid');
      const mine = form.get('mine');
      if (mine !== null) r.my.paid = !r.my.paid;
      else if (pid) r.people = r.people.map((pp) => (pp.id === pid ? { ...pp, paid: !pp.paid } : pp));
      await env.OTP_KV.put(key, JSON.stringify(r), { expirationTtl: SPLIT_TTL });
      return new Response(null, { status: 303, headers: { Location: url.pathname } });
    }

    const row = (label, paid, hidden, shareFmt) => `
      <form method="post" style="margin:0;">${hidden}
        <button type="submit" style="width:100%;display:flex;align-items:center;gap:12px;text-align:left;background:${paid ? '#F1F6F2' : '#fff'};border:1px solid ${paid ? '#CFE3D6' : '#E3E6E8'};border-radius:14px;padding:14px 16px;margin-bottom:10px;font-size:16px;font-family:inherit;color:#1A1D20;">
          <span style="display:inline-flex;width:22px;height:22px;">${paid
            ? '<svg width="22" height="22" viewBox="0 0 24 24" fill="none"><circle cx="12" cy="12" r="10" fill="#165B33"/><path d="M8 12.5l2.6 2.6L16 9.7" stroke="#FFFFFF" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round"/></svg>'
            : '<svg width="22" height="22" viewBox="0 0 24 24" fill="none"><circle cx="12" cy="12" r="9" stroke="#ADB5BD" stroke-width="2"/></svg>'}</span>
          <span style="flex:1;${paid ? 'text-decoration:line-through;color:#6C757D;' : ''}">${esc(label)}</span>
          <span style="font-weight:700;color:${paid ? '#6C757D' : '#165B33'};">${esc(shareFmt || r.shareFmt)}</span>
        </button>
      </form>`;
    const doneCount = r.people.filter((pp) => pp.paid).length + (r.my.included && r.my.paid ? 1 : 0);
    const totalCount = r.people.length + (r.my.included ? 1 : 0);
    const mathLine = r.even === false
      ? `${esc(r.totalFmt)} total \u00b7 <b style="color:#165B33;">custom shares</b> \u00b7 ${doneCount}/${totalCount} settled`
      : `${esc(r.totalFmt)} \u00f7 ${r.headcount} = <b style="color:#165B33;">${esc(r.shareFmt)} each</b> \u00b7 ${doneCount}/${totalCount} settled`;
    const html = `<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(r.title)}</title></head>
<body style="font-family:-apple-system,Segoe UI,Arial,sans-serif;background:#FAF9F6;color:#1A1D20;margin:0;padding:28px 20px;">
  <div style="max-width:440px;margin:0 auto;">
    <div style="font-size:13px;color:#6C757D;">You covered this one</div>
    <h2 style="margin:4px 0 6px;font-size:24px;">${esc(r.title)}</h2>
    <div style="color:#6C757D;font-size:14px;margin-bottom:18px;">${mathLine}</div>
    ${r.my.included ? row(r.my.label, r.my.paid, '<input type="hidden" name="mine" value="1">', r.my.shareFmt) : ''}
    ${r.people.map((pp) => row(pp.name, pp.paid, `<input type="hidden" name="pid" value="${esc(pp.id)}">`, pp.shareFmt)).join('')}
    <div style="color:#ADB5BD;font-size:12px;margin-top:16px;line-height:1.6;">This link was generated by ${esc(r.userName)}. Tap a name to tick off who already paid you. The link expires in 15 days.</div>
  </div>
</body></html>`;
    return new Response(html, { headers: { 'Content-Type': 'text/html; charset=utf-8', ...CORS } });
  }

  return json({ ok: false, reason: 'not-found' }, 404);
}

